// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address nonOwner) public {
        vm.assume(nonOwner != address(0));
        // Initialize to set the owner to msg.sender of setup (this contract)
        c.initialize();
        address actualOwner = c.owner();
        // nonOwner must be different from the actual owner
        vm.assume(nonOwner != actualOwner);
        bool equal = false;
        try c.owner{from: nonOwner}() returns (address o) {
            equal = (o == actualOwner);
        } catch {}
        // owner() must always return the same address, regardless of caller
        assertTrue(equal);
    }
}

