pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address constant OWNER = address(uint160(1));

    function setUp() public {
        c = new C();
        c.initialize();
        vm.startPrank(OWNER);
    }

    function testFuzz_property(address newOwner) public {
        // Admissible domain: full address space, no restricts needed
        // Transfer ownership to the fuzzed address
        c.transferOwnership(newOwner);

        // The general rule: after ANY transferOwnership call, the owner must never be the zero address.
        // The reference satisfies this; the mutant allows transferring to zero, breaking the invariant.
        assertTrue(c.owner() != address(0));
    }
}

