pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        c.initialize();
        assertEq(c.owner(), address(this));
        vm.prank(caller);
        (bool ok, bytes memory ret) = address(c).call(abi.encodeWithSignature("transferOwnership(address)", newOwner));
        bool revertHappened = !ok;
        assertTrue(revertHappened || c.owner() != address(this), "transferOwnership must revert for non-owner, or owner must change");
        assertEq(c.owner(), address(this));
    }
}

