import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newImpl) public {
        // Initialize the contract
        c.initialize();
        // Set alloSettings to non-zero so create wouldn't revert (though we only test updateRoundImplementation)
        c.updateAlloSettings(address(0x100));
        // Fuzzed new implementation address
        vm.prank(c.owner());
        c.updateRoundImplementation(newImpl);
        // The property: roundImplementation must never be zero after updateRoundImplementation
        assertTrue(c.roundImplementation() != address(0));
    }
}

