// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address payable newImpl) public {
        // The owner must call updateRoundImplementation. Make the test contract the owner.
        // The reference C's initializer sets msg.sender as owner; setUp() runs the Test contract construction,
        // then deploys C, then calls c.initialize() implicitly? No, C's initialize is external initializer.
        // We must call initialize to set owner and initial state.
        // We'll call initialize as the Test contract itself, so the Test contract becomes owner.
        vm.prank(address(this));
        c.initialize();

        // Record success of updateRoundImplementation call and resulting stored value.
        bool callOk;
        try c.updateRoundImplementation(newImpl) {
            callOk = true;
        } catch {
            callOk = false;
        }

        // For reference C, if call succeeded, newImpl != address(0) must hold (due to require),
        // and the stored roundImplementation must equal newImpl.
        // For buggy M, call always succeeds, even for address(0), and roundImplementation becomes newImpl (including 0).
        // The general rule: If the call succeeds, then stored roundImplementation == newImpl.
        // In reference C, this holds for any newImpl because the call only succeeds when newImpl != 0,
        // and after storage it equals newImpl. In buggy M, the call always succeeds, so for newImpl = 0,
        // stored roundImplementation == 0, which still satisfies the rule (0 == 0). That does NOT distinguish.
        // We need a rule that reference satisfies for ALL inputs (even those where call fails) and bug breaks for some.
        // Reference C requires newImpl != address(0). For newImpl = 0, it reverts; callOk = false.
        // So for all newImpl, reference C satisfies: callOk => roundImplementation() == newImpl.
        // For newImpl = 0 in reference, callOk is false, implication holds vacuously.
        // For buggy M, callOk is true for newImpl = 0, and then roundImplementation() == 0 == newImpl, implication holds as well! So this rule doesn't distinguish.
        // We must capture that reference never stores 0, while bug can.
        // Rule: roundImplementation() != address(0). Does reference satisfy this for ALL inputs?
        // After initialization, roundImplementation is 0 because never set. That would fail the rule.
        // We need to restrict to states after a call to updateRoundImplementation.
        // But fuzzer can supply any newImpl; we can call updateRoundImplementation only if owner is a valid caller.
        // We can make the fuzzer supply newImpl, but we can also set roundImplementation to some non-zero value first?
        // The state before updateRoundImplementation might be 0; then if we call with newImpl=0 and it succeeds,
        // roundImplementation stays 0. In reference, that call reverts, leaving it 0 as well (no change).
        // So post-call roundImplementation could be 0 in both if previously 0 and call reverts in reference, or call succeeds in bug but sets to 0.
        // That doesn't give a difference.

        // Alternative: set roundImplementation to a non-zero value first via a valid update, then call with newImpl=0.
        // Reference: call reverts, roundImplementation remains old non-zero value.
        // Bug: call succeeds, roundImplementation becomes 0.
        // Then rule: after calling updateRoundImplementation, if previous roundImplementation != 0, the new roundImplementation != 0.
        // But we need to express as a single assertion on c's public surface after the fuzzed call.
        // We can use a setup: call updateRoundImplementation with a non-zero address to set a baseline, then call with fuzzed newImpl, then assert.
        // That uses two calls. The test can include both.

        // Let's implement:
        // 1. Deploy a non-zero implementation address (we can use address(this) or a new contract).
        // 2. Call updateRoundImplementation with that non-zero address to establish a non-zero roundImplementation.
        // 3. Fuzz newImpl.
        // 4. Attempt to call updateRoundImplementation(newImpl) as owner.
        // 5. After the call (or revert), assert that roundImplementation != address(0) OR something else?

        // But the reference contract also has a require that alloSettings is not zero when creating a round.
        // We're not testing create.

        // The difference is simply that reference prevents roundImplementation from becoming 0 after a successful update (because it reverts on 0 argument).
        // The bug allows it to become 0.
        // So after any call to updateRoundImplementation that doesn't revert, roundImplementation != 0.
        // In reference, all non-reverting calls satisfy this; in bug, a call with newImpl=0 does not revert and makes it 0.
        // That's a valid property.

        // To test: we need to ensure the call succeeds (either in reference for non-zero, or in bug for any).
        // We'll assert: if the call succeeded, then roundImplementation() != 0.
        // Reference: for newImpl=0, call reverts -> callOk false, assertion not triggered. For newImpl!=0, call succeeds -> roundImplementation != 0.
        // Bug: for newImpl=0, call succeeds -> callOk true, but roundImplementation == 0 -> assertion fails.

        // But we also need to handle the state before the call. If roundImplementation is already 0 and we call with newImpl=0, both might revert or succeed, but we'd be asserting on a state that was already 0. To avoid false positives due to pre-existing 0, we can require that before the call roundImplementation != 0. But the property must hold for all admissible inputs. The fuzzer could start with roundImplementation == 0 if we don't set it. We'll set it via a first update to a known non-zero address (the test contract itself or a dummy). This ensures the pre-condition is satisfied.

        // Step 1: Initialize C and set owner (Test contract).
        // Already done above.

        // Step 2: Set roundImplementation to a non-zero address (e.g., address(this)).
        vm.prank(address(this));
        c.updateRoundImplementation(payable(address(this)));
        // Now roundImplementation is address(this).

        // Step 3: Attempt updateRoundImplementation with fuzzed newImpl.
        bool ok;
        try c.updateRoundImplementation(newImpl) {
            ok = true;
        } catch {
            ok = false;
        }

        // Step 4: Assert that if call succeeded, roundImplementation is not zero.
        if (ok) {
            assertTrue(c.roundImplementation() != address(0));
        }
        // If call failed, no assertion (vacuously true).
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        c.initialize();
        // make msg.sender the owner
        vm.prank(address(this));
        c.transferOwnership(address(this));
    }
    function testFuzz_property(address newRoundImpl) public {
        vm.assume(newRoundImpl != address(0));
        vm.prank(address(this));
        try c.updateRoundImplementation(payable(newRoundImpl)) {
            assertEq(c.roundImplementation(), newRoundImpl);
        } catch {
            fail();
        }
    }
}
